#!/usr/bin/env bash
# Generate the repository-root go.work from the Go modules under packages/.
#
# go.work exists for the editor and for the cross-module vet (go-work-vet) only.
# Nix builds and hook runs set GOWORK=off, so a build still resolves each module
# through its own go.mod (the replace lines there stay the build's truth).
#
# Usage:
#   gen-go-work.sh [--root DIR]           print the generated file to stdout
#   gen-go-work.sh [--root DIR] --write   write DIR/go.work
#   gen-go-work.sh [--root DIR] --check   exit 1 when DIR/go.work differs from the
#                                         generated file (the drift check)
set -euo pipefail

root=""
mode="print"
while [ "$#" -gt 0 ]; do
  case "$1" in
  --root)
    root="${2:?--root needs a directory}"
    shift 2
    ;;
  --write)
    mode="write"
    shift
    ;;
  --check)
    mode="check"
    shift
    ;;
  *)
    echo "gen-go-work.sh: unknown argument: $1" >&2
    exit 2
    ;;
  esac
done
if [ -z "${root}" ]; then
  root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
fi

mods=()
for gomod in "${root}"/packages/*/go.mod; do
  [ -e "${gomod}" ] || continue
  mods+=("$(basename "$(dirname "${gomod}")")")
done
if [ "${#mods[@]}" -eq 0 ]; then
  echo "gen-go-work.sh: found no packages/*/go.mod under ${root}" >&2
  exit 1
fi

# The go directive every module carries (go-deps-wired keeps them equal).
goversion="$(sed -n 's/^go[[:space:]]\{1,\}\([0-9][0-9.]*\)[[:space:]]*$/\1/p' "${root}/packages/${mods[0]}/go.mod" | head -n 1)"
if [ -z "${goversion}" ]; then
  echo "gen-go-work.sh: packages/${mods[0]}/go.mod has no go directive" >&2
  exit 1
fi

generate() {
  printf '// Generated by scripts/gen-go-work.sh; do not edit.\n'
  printf '// For the editor and the go-work-vet gate only: nix builds and hook runs set GOWORK=off.\n\n'
  printf 'go %s\n\nuse (\n' "${goversion}"
  printf '%s\n' "${mods[@]}" | LC_ALL=C sort | while IFS= read -r m; do
    printf '\t./packages/%s\n' "${m}"
  done
  printf ')\n'
}

case "${mode}" in
print) generate ;;
write) generate >"${root}/go.work" ;;
check)
  if [ ! -f "${root}/go.work" ]; then
    echo "FAIL: ${root}/go.work is missing; run scripts/gen-go-work.sh --write" >&2
    exit 1
  fi
  if ! generate | diff -u "${root}/go.work" - >&2; then
    echo "FAIL: go.work drifted from the generated file; run scripts/gen-go-work.sh --write" >&2
    exit 1
  fi
  echo "OK: go.work matches the generated file (${#mods[@]} modules)."
  ;;
esac
